import{_ as s,c as e,a as n,o as l}from"./app-C8nc19Re.js";const i={};function o(c,a){return l(),e("div",null,a[0]||(a[0]=[n(`<h2 id="在线预览" tabindex="-1"><a class="header-anchor" href="#在线预览"><span>在线预览</span></a></h2><div class="hint-container info"><p class="hint-container-title">地址</p><p><a href="https://echoyl.com/antadmin/example/news/news" target="_blank" rel="noopener noreferrer">点击查看</a></p></div><h2 id="基础" tabindex="-1"><a class="header-anchor" href="#基础"><span>基础</span></a></h2><h3 id="简介" tabindex="-1"><a class="header-anchor" href="#简介"><span>简介</span></a></h3><p>表格列表页面是后台管理系统中最常见的页面之一，用于展示和管理数据列表。在 DeAdmin 中，我们提供了灵活且强大的表格组件，支持自定义表头、列宽、排序等功能，满足各种业务需求。 支持大部分常见的需求功能，如：搜索栏、头部操作栏、底部操作栏、内置列、默认请求参数、合计等。</p><h3 id="开发时编辑" tabindex="-1"><a class="header-anchor" href="#开发时编辑"><span>开发时编辑</span></a></h3><div class="hint-container info"><p class="hint-container-title">快速的开发体验，一个表格只要勾选字段即可完成开发，无需编写任何代码</p><p>支持快速勾选需要选择的字段，拖拽排序字段显示顺序，拖动列宽，单个列头右键菜单后编辑详细自定义等。 更多配置还可以菜单设置中进行设置，比如设置表格的大小，滚动宽度，分页配置等</p></div><h3 id="列的条件显示" tabindex="-1"><a class="header-anchor" href="#列的条件显示"><span>列的条件显示</span></a></h3><p>编辑该列设置<code>显示条件</code></p><div class="language-json line-numbers-mode" data-highlighter="shiki" data-ext="json" style="background-color:#24292e;color:#e1e4e8;"><pre class="shiki github-dark vp-code"><code><span class="line"><span style="color:#E1E4E8;">{ </span><span style="color:#79B8FF;">&quot;record&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;当前请求返回search数据&quot;</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">&quot;user&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;当前登录用户&quot;</span><span style="color:#E1E4E8;"> }</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>示例 <code>{{user.role_id == 1}}</code> 表示如果用户的角色 id 为 1 则显示该列</p><h3 id="搜索栏" tabindex="-1"><a class="header-anchor" href="#搜索栏"><span>搜索栏</span></a></h3><p>编辑需要搜索的列，勾选<code>可搜索</code>，如果只要搜索不展示在列表中，勾选<code>表中隐藏</code>即可</p><h3 id="toolbar-头部操作栏" tabindex="-1"><a class="header-anchor" href="#toolbar-头部操作栏"><span>Toolbar 头部操作栏</span></a></h3><p>位于表头头部的操作栏展示，提交数据默认带入 ids:[] 所勾选的表格数据</p><ul><li>1.插入字段类型选择 <code>头部操作栏 - toolbar</code></li><li>2.更多设置中编辑自定义 dom（自定义组件设置）</li><li>3.提供<code>导出</code>及<code>导入</code>两种字段类型，快速展示出该两个功能按钮，默认 url + export | import 后台逻辑需要自行实现</li></ul><h3 id="selectbar-底部操作栏" tabindex="-1"><a class="header-anchor" href="#selectbar-底部操作栏"><span>Selectbar 底部操作栏</span></a></h3><p>位于表格底部操作栏展示，需要勾选表格数据后才会展示，提交数据默认带入 ids:[] 所勾选的表格数据</p><ul><li>1.插入字段类型选择 <code>底部选择操作栏 - selectbar</code></li><li>2.更多设置中编辑自定义 dom（自定义组件设置）</li><li>3.默认加入批量删除功能，菜单编辑中关闭可删除后不展示该按钮</li><li>4.默认保留字段名称 请求返回数据 search.states 有数据的话会展示该批量设置按钮，如<code>启用</code> <code>禁用</code></li></ul><h3 id="内置列" tabindex="-1"><a class="header-anchor" href="#内置列"><span>内置列</span></a></h3><ul><li>1.排序功能 字段 <code>displayorder</code> 默认在列表中展示排序输入框 输入后修改该记录排序值</li><li>2.操作栏 默认包含 <code>编辑</code> <code>删除</code> 3 个功能按键，菜单关闭 <code>可编辑</code> <code>可删除</code>后 隐藏 <code>编辑</code>和<code>删除</code></li><li>3.可添加自定义列，在 dom 中添加 <code>查看</code> 按钮。或其它操作按钮</li></ul><h3 id="默认请求参数" tabindex="-1"><a class="header-anchor" href="#默认请求参数"><span>默认请求参数</span></a></h3><p>当前页面需要自带自定义参数时使用 在编辑菜单页面 - 其他配置中加入下方设置</p><div class="language-json line-numbers-mode" data-highlighter="shiki" data-ext="json" style="background-color:#24292e;color:#e1e4e8;"><pre class="shiki github-dark vp-code"><code><span class="line"><span style="color:#E1E4E8;">{</span></span>
<span class="line"><span style="color:#79B8FF;">	&quot;paramExtra&quot;</span><span style="color:#E1E4E8;">: {</span></span>
<span class="line"><span style="color:#79B8FF;">		&quot;key_name&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;key_value&quot;</span></span>
<span class="line"><span style="color:#E1E4E8;">	}</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="summary-合计" tabindex="-1"><a class="header-anchor" href="#summary-合计"><span>summary 合计</span></a></h3><p>在数据接口中返回 <code>search.summary</code> 字段</p><div class="language-php line-numbers-mode" data-highlighter="shiki" data-ext="php" style="background-color:#24292e;color:#e1e4e8;"><pre class="shiki github-dark vp-code"><code><span class="line"></span>
<span class="line"><span style="color:#F97583;">public</span><span style="color:#F97583;"> function</span><span style="color:#B392F0;"> handleSearch</span><span style="color:#E1E4E8;">($search </span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;"> [])</span></span>
<span class="line"><span style="color:#E1E4E8;">{</span></span>
<span class="line"><span style="color:#E1E4E8;">    $m </span><span style="color:#F97583;">=</span><span style="color:#79B8FF;"> $this</span><span style="color:#F97583;">-&gt;</span><span style="color:#B392F0;">getModel</span><span style="color:#E1E4E8;">();</span></span>
<span class="line"><span style="color:#E1E4E8;">    $search[</span><span style="color:#9ECBFF;">&#39;summary&#39;</span><span style="color:#E1E4E8;">] </span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;"> &#39;&lt;span style=&quot;color:red&quot;&gt;合计 ：可以是一段自定义html&lt;/span&gt;&#39;</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#F97583;">    return</span><span style="color:#E1E4E8;"> [$m, $search];</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="搜索" tabindex="-1"><a class="header-anchor" href="#搜索"><span>搜索</span></a></h2><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>这里我们使用搜索会员性别为例</p></div><h3 id="编辑模型添加搜项" tabindex="-1"><a class="header-anchor" href="#编辑模型添加搜项"><span>编辑模型添加搜项</span></a></h3><p>这里添加设置后会在 php 文件中自动加入该项的搜索设置，如果取消这部的话需要自己在 php 控制器中加入搜索逻辑代码</p><ul><li><p>添加一行搜索配置 url 参数名称 填入 gender（url 名称就是请求后台的参数名，可以自由设置）</p></li><li><p>搜索类型选择 <code>=</code>，这里支持 <code>=</code>,<code>like</code>,<code>whereBetween</code>,<code>whereIn</code>,<code>has</code>,<code>doesntHave</code></p></li><li><p>字段选择 gender 字段,字段支持选择多个</p></li><li><p><img src="https://echoyl.com/storage/images/202408/rn7SVDPRiq0JkkkHo4i1Z6pb66mrg3rC3sttbeyJ.png" alt="image"></p></li></ul><p>保存后 php 代码会变成这样</p><div class="language-php line-numbers-mode" data-highlighter="shiki" data-ext="php" style="background-color:#24292e;color:#e1e4e8;"><pre class="shiki github-dark vp-code"><code><span class="line"><span style="color:#79B8FF;">$this</span><span style="color:#F97583;">-&gt;</span><span style="color:#E1E4E8;">search_config </span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;"> [</span></span>
<span class="line"><span style="color:#E1E4E8;">		    [</span></span>
<span class="line"><span style="color:#9ECBFF;">		        &#39;name&#39;</span><span style="color:#F97583;"> =&gt;</span><span style="color:#9ECBFF;"> &#39;gender&#39;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#9ECBFF;">		        &#39;columns&#39;</span><span style="color:#F97583;"> =&gt;</span><span style="color:#E1E4E8;"> [</span></span>
<span class="line"><span style="color:#9ECBFF;">		            &#39;gender&#39;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#E1E4E8;">		        ],</span></span>
<span class="line"><span style="color:#9ECBFF;">		        &#39;where_type&#39;</span><span style="color:#F97583;"> =&gt;</span><span style="color:#9ECBFF;"> &#39;=&#39;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#E1E4E8;">		    ],</span></span>
<span class="line"><span style="color:#E1E4E8;">		];</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="在列表页面加入搜索设置" tabindex="-1"><a class="header-anchor" href="#在列表页面加入搜索设置"><span>在列表页面加入搜索设置</span></a></h3><p>因为当前性别列在列表中已经以自定义组件显示，所以搜索字段需要新增一列</p><p><img src="https://echoyl.com/storage/images/202408/YAbT0LSgm9tzLuKJ9hB1bgfguU2gTcQHfUAIjWO6.png" alt="image"></p><h3 id="设置默认的表单值" tabindex="-1"><a class="header-anchor" href="#设置默认的表单值"><span>设置默认的表单值</span></a></h3><p>在当前项设置中，整体配置加入 <code>initialValue</code> 值即可设置默认搜索值 加入默认值后点击重置按钮搜索项默认会使用该默认值，只有点击搜索项的 × 按钮后再点击搜索才不会使用默认值搜索。 之前使用 ret.search.values 后配置这个默认值，导致必须 1.后台获取搜索值的时候前端未传值后会使用默认值，导致无法清空搜索值。 ps：现在直接在配置中设置默认值。日期的话使用 dayjs 代码后程序直接会进行格式化。</p><div class="language-json line-numbers-mode" data-highlighter="shiki" data-ext="json" style="background-color:#24292e;color:#e1e4e8;"><pre class="shiki github-dark vp-code"><code><span class="line"><span style="color:#E1E4E8;">{</span></span>
<span class="line"><span style="color:#79B8FF;">	&quot;initialValue&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">1</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>日期格式化 使用<code>dayjs</code>组件自行设置</p><div class="language-json line-numbers-mode" data-highlighter="shiki" data-ext="json" style="background-color:#24292e;color:#e1e4e8;"><pre class="shiki github-dark vp-code"><code><span class="line"><span style="color:#E1E4E8;">{</span></span>
<span class="line"><span style="color:#79B8FF;">	&quot;initialValue&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;{{dayjs().format(&#39;YYYY-MM-DD&#39;)}}&quot;</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="搜索功能完成-效果图" tabindex="-1"><a class="header-anchor" href="#搜索功能完成-效果图"><span>搜索功能完成 效果图</span></a></h3><p><img src="https://echoyl.com/storage/images/202408/jFLi9SY6GaRyQ94fxKCJyjR8O1wO3Q5i1lFNWLhP.png" alt="image"></p><h2 id="tab-筛选" tabindex="-1"><a class="header-anchor" href="#tab-筛选"><span>Tab 筛选</span></a></h2><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>tab 筛选一般是列表中优先级最高的快捷检索，一般默认都会是数据的启用与禁用的状态，这次我们以会员的<code>性别</code>和<code>启用禁用</code>状态作为示例来设置列表页的<code>tab筛选</code></p></div><h3 id="设置模型字段支持-tab" tabindex="-1"><a class="header-anchor" href="#设置模型字段支持-tab"><span>设置模型字段支持 tab</span></a></h3><p>可以设置多个字段是否支持 tab，开启后列表返回数据会将可选数据放入到 table_menu 数据中以供前端消费</p><p><img src="https://echoyl.com/storage/images/202408/7Ca8tDxpT4IJ9b1xyZeACeP3Uh4XtBg0MHbMINfS.png" alt="image"></p><h3 id="在列表中设置" tabindex="-1"><a class="header-anchor" href="#在列表中设置"><span>在列表中设置</span></a></h3><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>备注 开启 tab 筛选至少要 在搜索表单中或者列表中有展示，不然下次找不到设置的地方了。</p></div><ul><li>先设置状态字段 点击开启 tab</li><li><img src="https://echoyl.com/storage/images/202408/gVBmTUN9SyPlHoCVtIiZ6jIKtplJUUeHVDkK579i.png" alt="image"></li><li>效果如下</li><li><img src="https://echoyl.com/storage/images/202408/vUX6KlAAfd3HDXgZc04UuMP1RLboxVonVUeu2Jv6.png" alt="image"></li></ul><h3 id="切换为性别筛选" tabindex="-1"><a class="header-anchor" href="#切换为性别筛选"><span>切换为性别筛选</span></a></h3><ul><li>关闭刚才勾选的状态 tab</li><li>在性别设置中开启 tab</li><li>效果如下</li><li><img src="https://echoyl.com/storage/images/202408/RbxkAyvd11bHphg4x5SuVaqTV75Fk5BjbUq5Hj9q.png" alt="image"></li></ul><h3 id="设置默认选中项" tabindex="-1"><a class="header-anchor" href="#设置默认选中项"><span>设置默认选中项</span></a></h3><ul><li>假设我们默认要选中 女</li><li>编辑当前菜单在其它配置中加入<code>table_menu_default</code> 的配置 这里填入<code>female</code></li><li><img src="https://echoyl.com/storage/images/202408/ki3eDXhBBRe3JiZZjLNAKtO2lCz6YH3cgeP3mVUm.png" alt="image"></li><li>如果当前未选中或者刷新当前页面后默认选中的就是 female 的 tab 了</li><li><img src="https://echoyl.com/storage/images/202408/Kr94TSY0MlFObuCFqb0mhDy6UyvcNochlOYgR3UM.png" alt="image"></li></ul><h3 id="去掉-tab-默认追加的-全部选项" tabindex="-1"><a class="header-anchor" href="#去掉-tab-默认追加的-全部选项"><span>去掉 tab 默认追加的 全部选项</span></a></h3><p>默认开启 tab 后是会加入全部这个选项的，默认页是选中这个全部选项 关闭这个设置的话</p><ul><li>编辑当前菜单，在其它配置中配置<code>table_menu_all</code>:<code>false</code></li><li><img src="https://echoyl.com/storage/images/202408/ss6Zh5GoyvetKA1QRGc0rSFheM2ZCIIDoHQx1ncL.png" alt="image"></li><li>效果如下图</li><li><img src="https://echoyl.com/storage/images/202408/nWSgRujlTJZiQwhARw1WdNYLQxYQgUkfKz4GXKNz.png" alt="image"></li></ul><h2 id="卡片列表" tabindex="-1"><a class="header-anchor" href="#卡片列表"><span>卡片列表</span></a></h2><h3 id="简介-1" tabindex="-1"><a class="header-anchor" href="#简介-1"><span>简介</span></a></h3><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>卡片式列表适用于显示字段较少，包含封面图，标题，描述，及个别显示字段的信息展示。常用于项目，会员等信息展示</p></div><h3 id="配置" tabindex="-1"><a class="header-anchor" href="#配置"><span>配置</span></a></h3><p>配置和 table 差不多，需要额外的选项显示配置如下图所示</p><p><img src="https://echoyl.com/storage/images/202410/C8kuGeKfbl3KCPs7ACLCAOCXZQG14KandeUjb0yg.png" alt="image"></p><h3 id="支持功能" tabindex="-1"><a class="header-anchor" href="#支持功能"><span>支持功能</span></a></h3><ul><li>功能和 table 基本相同，下面是不同点</li><li>勾选 使用 checkcard 的样式展示</li><li>除了固定的封面，标题，描述外，最后一行展示是使用 flex 布局，可以插入自定显示信息。支持类型为 option 和 自定义组件，内容显示。</li></ul><h3 id="整体效果显示" tabindex="-1"><a class="header-anchor" href="#整体效果显示"><span>整体效果显示</span></a></h3><p><img src="https://echoyl.com/storage/images/202410/3089suZKgkiWYNmUc4zqMieemTEo7uldvyFicGLR.png" alt="image"></p><h3 id="总结" tabindex="-1"><a class="header-anchor" href="#总结"><span>总结</span></a></h3><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>该组件直接使用 ProList 封装，得益于 ProList 是基于 ProTable 的，所以我们实现这个功能只要继续向下拓展 SaTable，然后实现单个信息的 coverItem 卡片样式的显示即完成该功能</p></div>`,71)]))}const t=s(i,[["render",o]]),r=JSON.parse('{"path":"/guide/page/table/","title":"表格","lang":"zh-CN","frontmatter":{"title":"表格","createTime":"2025/11/07 10:15:14","permalink":"/guide/page/table/"},"readingTime":{"minutes":6,"words":1801},"git":{"updatedTime":1762497002000,"contributors":[{"name":"echoyl","username":"echoyl","email":"inandan@126.com","commits":1,"avatar":"https://avatars.githubusercontent.com/echoyl?v=4","url":"https://github.com/echoyl"}]},"filePathRelative":"notes/guide/page/table.md","headers":[]}');export{t as comp,r as data};
